import itertools
S=[(3.5,17.5),(3.5,25.5),(11.5,17.5),(11.5,25.5)]
P={'2':(4.5,7.5),'6':(18.5,7.5),'3':(22.5,23.5),'4':(25.5,13.5)}
for norm in ['L1','L2']:
 best=[]
 for perm in itertools.permutations(P):
  ds=[]
  for a,b in zip(S,perm):
   x,y=P[b]; d=abs(a[0]-x)+abs(a[1]-y) if norm=='L1' else ((a[0]-x)**2+(a[1]-y)**2)**.5
   ds.append(d)
  best.append((sum(ds),perm,ds))
 print(norm, sorted(best)[:3])

import itertools
shells={'7':{(2,2),(5,5)},'1':{(2,2),(2,5),(5,5)},'3':{(2,2),(2,5),(5,2),(5,5)},'5':{(2,2)}}
inner={'2':{(2,2),(2,4),(2,5),(3,2),(3,4),(3,5),(4,2),(5,2),(5,4),(5,5)},'6':{(2,2),(2,4),(2,5),(3,2),(3,4),(3,5),(5,2),(5,4),(5,5)},'3':{(r,c) for r in range(2,6) for c in range(2,6)},'4':{(2,5),(4,5),(5,5)}}
for metric in ['overlap','jaccard','subset']:
 vals=[]
 for p in itertools.permutations(inner):
  scores=[]
  for s,i in zip(shells,p):
   a,b=shells[s],inner[i]; inter=len(a&b)
   sc=inter if metric=='overlap' else inter/len(a|b) if metric=='jaccard' else inter/len(a)
   scores.append(sc)
  vals.append((sum(scores),p,scores))
 print(metric, sorted(vals,reverse=True)[:3])

